#include "stdlib/blas/ext/base/scircshift.h"
#include "stdlib/blas/ext/base/srev.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Performs a circular shift on a single-precision floating-point strided array in-place.
*
* @param N        number of indexed elements
* @param k        number of positions to shift
* @param X        input array
* @param strideX  stride length
*/
void API_SUFFIX(stdlib_strided_scircshift)( const CBLAS_INT N, const CBLAS_INT k, float *X, const CBLAS_INT strideX ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	API_SUFFIX(stdlib_strided_scircshift_ndarray)( N, k, X, strideX, ox );
}

/**
* Performs a circular shift on a single-precision floating-point strided array in-place using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param k        number of positions to shift
* @param X        input array
* @param strideX  stride length
* @param offsetX  starting index
*/
void API_SUFFIX(stdlib_strided_scircshift_ndarray)( const CBLAS_INT N, const CBLAS_INT k, float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT nk;

	if ( N <= 0 ) {
		return;
	}

	// Normalize `k`...
	nk = k % N;
	if ( nk < 0 ) {
		nk += N;
	}
	if ( nk == 0 ) {
		return;
	}

	// Reverse the entire array:
	API_SUFFIX(stdlib_strided_srev_ndarray)( N, X, strideX, offsetX );

	// Reverse the first `nk` elements:
	API_SUFFIX(stdlib_strided_srev_ndarray)( nk, X, strideX, offsetX );

	// Reverse the last `N-nk` elements:
	API_SUFFIX(stdlib_strided_srev_ndarray)( N - nk, X, strideX, offsetX + ( nk * strideX ) );
}
